"use client";
/**
 * @description A modal dialog that interrupts the user with important content and expects a response.
 */
import * as React from "react";
import { AlertDialog as AlertDialogRadix } from "radix-ui";

import { cn } from "@/utils/class-names";

function AlertDialog({
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Root>) {
  return <AlertDialogRadix.Root data-slot="alert-dialog" {...props} />;
}

function AlertDialogTrigger({
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Trigger>) {
  return (
    <AlertDialogRadix.Trigger data-slot="alert-dialog-trigger" {...props} />
  );
}

function AlertDialogPortal({
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Portal>) {
  return <AlertDialogRadix.Portal data-slot="alert-dialog-portal" {...props} />;
}

function AlertDialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Overlay>) {
  return (
    <AlertDialogRadix.Overlay
      data-slot="alert-dialog-overlay"
      className={cn(
        "aura-overlay z-50",
        className
      )}
      {...props}
    />
  );
}

function AlertDialogContent({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Content>) {
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogRadix.Content
        data-slot="alert-dialog-content"
        className={cn(
          "smash fixed left-1/2 top-1/2 max-h-[85vh] w-[90vw] -translate-x-1/2 -translate-y-1/2 bg-gray-1 p-2 rounded-md z-50 data-[state=open]:animate-content-show border border-gray-a6",
          className
        )}
        {...props}
      />
    </AlertDialogPortal>
  );
}

function AlertDialogHeader({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn("", className)}
      {...props}
    />
  );
}

function AlertDialogFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn(
        "flex-col-reverse md:flex-row flex justify-end gap-1 md:gap-2",
        className
      )}
      {...props}
    />
  );
}

function AlertDialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Title>) {
  return (
    <AlertDialogRadix.Title
      data-slot="alert-dialog-title"
      className={cn("m-0", className)}
      {...props}
    />
  );
}

function AlertDialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Description>) {
  return (
    <AlertDialogRadix.Description
      data-slot="alert-dialog-description"
      className={cn("", className)}
      {...props}
    />
  );
}

function AlertDialogAction({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Action>) {
  return <AlertDialogRadix.Action className={cn("", className)} {...props} />;
}

function AlertDialogCancel({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogRadix.Cancel>) {
  return <AlertDialogRadix.Cancel className={cn("", className)} {...props} />;
}

export {
  AlertDialog,
  AlertDialogPortal,
  AlertDialogOverlay,
  AlertDialogTrigger,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogAction,
  AlertDialogCancel,
};

@theme animations {
    --animate-overlay-show: overlayShow 150ms cubic-bezier(0.16, 1, 0.3, 1);
    --animate-content-show: contentShow 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  @layer components {
    @keyframes overlayShow {
      from {
        opacity: 0;
      }
      to {
        opacity: 1;
      }
    }

    @keyframes contentShow {
      from {
        opacity: 0;
        transform: scale(0.96);
      }
      to {
        opacity: 1;
        transform: scale(1);
      }
    }
  }

@media (prefers-reduced-motion: reduce) {
  @layer components {
    [data-slot="alert-dialog-overlay"],
    [data-slot="alert-dialog-content"] {
      animation: none;
    }
  }
}

/*
 * Shared modal scrim for every Aura overlay.
 *
 * --aura-overlay is rgb(16 11 33 / 0.08): dark gray-1 (#100B21) at 8%.
 * The same value is set in light and dark in registry globals. It is not
 * var(--gray-1), because gray-1 is near-white in light mode.
 * Declared here as well so the tint ships with this file.
 * backdrop-filter matches backdrop-blur-xs (--blur-xs is 4px).
 * Enter fade is opacity 0 to 1, 150ms, cubic-bezier(0.16, 1, 0.3, 1).
 *
 * `@theme animatons` (the typo) still registered --animate-* tokens. Tailwind v4
 * ignores unknown @theme words; it does not drop the custom properties.
 * sheet.css and alert-dialog.css use `@theme animations`.
 */

:root {
  --aura-overlay: rgb(16 11 33 / 0.08);
}

@keyframes aura-overlay-show {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes aura-overlay-hide {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

.aura-overlay {
  position: fixed;
  inset: 0;
  background-color: var(--aura-overlay);
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
}

.aura-overlay[data-state="open"] {
  animation: aura-overlay-show 150ms cubic-bezier(0.16, 1, 0.3, 1);
}

/*
 * vaul injects an unlayered 500ms fadeIn/fadeOut on [data-vaul-overlay].
 * !important keeps the 150ms fade when this file is imported inside a layer.
 */
.aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="open"] {
  animation: aura-overlay-show 150ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="closed"] {
  animation: aura-overlay-hide 150ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.aura-overlay[data-starting-style],
.aura-overlay[data-ending-style] {
  opacity: 0;
}

@media (prefers-reduced-motion: no-preference) {
  .aura-overlay:is([data-open], [data-closed], [data-starting-style], [data-ending-style]) {
    transition: opacity 150ms cubic-bezier(0.16, 1, 0.3, 1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .aura-overlay,
  .aura-overlay[data-state="open"],
  .aura-overlay[data-state="closed"],
  .aura-overlay[data-starting-style],
  .aura-overlay[data-ending-style],
  .aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="open"],
  .aura-overlay[data-vaul-overlay][data-vaul-snap-points][data-state="closed"] {
    animation: none !important;
    transition: none;
    opacity: 1;
  }
}
